import { isSameDay, parseISO } from "date-fns";
import { useCalendar } from "./contexts/calendar-context";
import { AgendaEvents } from "./views/agenda-view/agenda-events";
import { CalendarMonthView } from "./views/month-view/calendar-month-view";
import { CalendarDayView } from "./views/week-and-day-view/calendar-day-view";
import { CalendarWeekView } from "./views/week-and-day-view/calendar-week-view";
import { CalendarYearView } from "./views/year-view/calendar-year-view";

export function CalendarBody() {
  const { view, events } = useCalendar();

  const singleDayEvents = events.filter((event) => {
    const startDate = parseISO(event.startDate);
    const endDate = parseISO(event.endDate);
    return isSameDay(startDate, endDate);
  });

  const multiDayEvents = events.filter((event) => {
    const startDate = parseISO(event.startDate);
    const endDate = parseISO(event.endDate);
    return !isSameDay(startDate, endDate);
  });

  return (
    <div className="w-full h-full overflow-scroll relative">
      <div key={view} className="animate-in fade-in duration-200">
        {view === "month" && (
          <CalendarMonthView
            singleDayEvents={singleDayEvents}
            multiDayEvents={multiDayEvents}
          />
        )}
        {view === "week" && (
          <CalendarWeekView
            singleDayEvents={singleDayEvents}
            multiDayEvents={multiDayEvents}
          />
        )}
        {view === "day" && (
          <CalendarDayView
            singleDayEvents={singleDayEvents}
            multiDayEvents={multiDayEvents}
          />
        )}
        {view === "year" && (
          <CalendarYearView
            singleDayEvents={singleDayEvents}
            multiDayEvents={multiDayEvents}
          />
        )}
        {view === "agenda" && <AgendaEvents />}
      </div>
    </div>
  );
}

import type { Locale } from "date-fns";

import { CalendarBody } from "./calendar-body";
import { CalendarProvider } from "./contexts/calendar-context";
import { DndProvider } from "./contexts/dnd-context";
import { CalendarHeader } from "./header/calendar-header";
import type { IEvent, IUser } from "./interfaces";
import type { CalendarLabels } from "./labels";
import type { TCalendarView } from "./types";

export interface CalendarProps {
  events: IEvent[];
  users: IUser[];
  view?: TCalendarView;
  badge?: "dot" | "colored";
  labels?: Partial<CalendarLabels>;
  locale?: Locale;
}

export function Calendar({
  events,
  users,
  view = "month",
  badge,
  labels,
  locale,
}: CalendarProps) {
  return (
    <CalendarProvider
      events={events}
      users={users}
      view={view}
      badge={badge}
      labels={labels}
      locale={locale}
    >
      <DndProvider>
        <div className="w-full border rounded-xl">
          <CalendarHeader />
          <CalendarBody />
        </div>
      </DndProvider>
    </CalendarProvider>
  );
}

import type { TEventColor } from "./types";

export const COLORS: TEventColor[] = [
  "blue",
  "green",
  "red",
  "yellow",
  "purple",
  "orange",
];

import type { Locale } from "date-fns";
import type React from "react";
import { createContext, useContext, useState } from "react";
import { useLocalStorage } from "../hooks";
import type { IEvent, IUser } from "../interfaces";
import { defaultCalendarLabels, type CalendarLabels } from "../labels";
import type { TCalendarView, TEventColor } from "../types";

interface ICalendarContext {
  selectedDate: Date;
  view: TCalendarView;
  setView: (view: TCalendarView) => void;
  agendaModeGroupBy: "date" | "color";
  setAgendaModeGroupBy: (groupBy: "date" | "color") => void;
  use24HourFormat: boolean;
  toggleTimeFormat: () => void;
  startOfDayHour: number;
  setStartOfDayHour: (newVal: number) => void;
  setSelectedDate: (date: Date | undefined) => void;
  selectedUserIds: IUser["id"][];
  badgeVariant: "dot" | "colored";
  setBadgeVariant: (variant: "dot" | "colored") => void;
  selectedColors: TEventColor[];
  filterEventsBySelectedColors: (colors: TEventColor) => void;
  filterEventsBySelectedUsers: (userId: IUser["id"]) => void;
  clearUserFilter: () => void;
  users: IUser[];
  events: IEvent[];
  addEvent: (event: IEvent) => void;
  updateEvent: (event: IEvent) => void;
  removeEvent: (eventId: number) => void;
  clearFilter: () => void;
  labels: CalendarLabels;
  locale?: Locale;
}

interface CalendarSettings {
  badgeVariant: "dot" | "colored";
  view: TCalendarView;
  use24HourFormat: boolean;
  startOfDayHour: number;
  agendaModeGroupBy: "date" | "color";
}

export const MIN_SCROLL_HOUR = 0;
// With a fixed calendar height, having 16h on top
// of the frame allows to see the rest of the day
export const MAX_SCROLL_HOUR = 16;

const DEFAULT_SETTINGS: CalendarSettings = {
  badgeVariant: "colored",
  view: "day",
  use24HourFormat: true,
  startOfDayHour: 8,
  agendaModeGroupBy: "date",
};

const CalendarContext = createContext({} as ICalendarContext);

export function CalendarProvider({
  children,
  users,
  events,
  badge = "colored",
  view = "day",
  labels,
  locale,
}: {
  children: React.ReactNode;
  users: IUser[];
  events: IEvent[];
  view?: TCalendarView;
  badge?: "dot" | "colored";
  labels?: Partial<CalendarLabels>;
  locale?: Locale;
}) {
  const [rawSettings, setSettings] = useLocalStorage<Partial<CalendarSettings>>(
    "calendar-settings",
    {},
  );

  const settings: CalendarSettings = {
    ...DEFAULT_SETTINGS,
    badgeVariant: badge,
    view: view,
    ...rawSettings,
  };

  const [badgeVariant, setBadgeVariantState] = useState<"dot" | "colored">(
    settings.badgeVariant,
  );
  const [currentView, setCurrentViewState] = useState<TCalendarView>(
    settings.view,
  );
  const [use24HourFormat, setUse24HourFormatState] = useState<boolean>(
    settings.use24HourFormat,
  );
  const [startOfDayHour, setStartOfDayHourState] = useState<number>(
    settings.startOfDayHour,
  );
  const [agendaModeGroupBy, setAgendaModeGroupByState] = useState<
    "date" | "color"
  >(settings.agendaModeGroupBy);

  const [selectedDate, setSelectedDate] = useState(new Date());
  const [selectedUserIds, setSelectedUserIds] = useState<IUser["id"][]>([]);
  const [selectedColors, setSelectedColors] = useState<TEventColor[]>([]);

  const [allEvents, setAllEvents] = useState<IEvent[]>(events || []);
  const [filteredEvents, setFilteredEvents] = useState<IEvent[]>(events || []);

  const updateSettings = (newPartialSettings: Partial<CalendarSettings>) => {
    setSettings((prev) => ({
      ...prev,
      ...newPartialSettings,
    }));
  };

  const setBadgeVariant = (variant: "dot" | "colored") => {
    setBadgeVariantState(variant);
    updateSettings({ badgeVariant: variant });
  };

  const setView = (newView: TCalendarView) => {
    setCurrentViewState(newView);
    updateSettings({ view: newView });
  };

  const toggleTimeFormat = () => {
    const newValue = !use24HourFormat;
    setUse24HourFormatState(newValue);
    updateSettings({ use24HourFormat: newValue });
  };

  const setStartOfDayHour = (newVal: number) => {
    if (
      !isNaN(newVal) &&
      newVal >= MIN_SCROLL_HOUR &&
      newVal <= MAX_SCROLL_HOUR
    ) {
      setStartOfDayHourState(newVal);
      updateSettings({ startOfDayHour: newVal });
    }
  };

  const setAgendaModeGroupBy = (groupBy: "date" | "color") => {
    setAgendaModeGroupByState(groupBy);
    updateSettings({ agendaModeGroupBy: groupBy });
  };

  const applyFilters = (colors: TEventColor[], userIds: IUser["id"][]) => {
    let filtered = allEvents;

    if (colors.length > 0) {
      filtered = filtered.filter((event) =>
        colors.includes(event.color || "blue"),
      );
    }

    if (userIds.length > 0) {
      filtered = filtered.filter((event) => userIds.includes(event.user.id));
    }

    setFilteredEvents(filtered);
  };

  const filterEventsBySelectedColors = (color: TEventColor) => {
    const isColorSelected = selectedColors.includes(color);
    const newColors = isColorSelected
      ? selectedColors.filter((c) => c !== color)
      : [...selectedColors, color];

    setSelectedColors(newColors);
    applyFilters(newColors, selectedUserIds);
  };

  const filterEventsBySelectedUsers = (userId: IUser["id"]) => {
    const isUserSelected = selectedUserIds.includes(userId);
    const newUserIds = isUserSelected
      ? selectedUserIds.filter((id) => id !== userId)
      : [...selectedUserIds, userId];

    setSelectedUserIds(newUserIds);
    applyFilters(selectedColors, newUserIds);
  };

  const clearUserFilter = () => {
    setSelectedUserIds([]);
    applyFilters(selectedColors, []);
  };

  const handleSelectDate = (date: Date | undefined) => {
    if (!date) return;
    setSelectedDate(date);
  };

  const addEvent = (event: IEvent) => {
    setAllEvents((prev) => [...prev, event]);
    setFilteredEvents((prev) => [...prev, event]);
  };

  const updateEvent = (event: IEvent) => {
    const updated = {
      ...event,
      startDate: new Date(event.startDate).toISOString(),
      endDate: new Date(event.endDate).toISOString(),
    };

    setAllEvents((prev) => prev.map((e) => (e.id === event.id ? updated : e)));
    setFilteredEvents((prev) =>
      prev.map((e) => (e.id === event.id ? updated : e)),
    );
  };

  const removeEvent = (eventId: number) => {
    setAllEvents((prev) => prev.filter((e) => e.id !== eventId));
    setFilteredEvents((prev) => prev.filter((e) => e.id !== eventId));
  };

  const clearFilter = () => {
    setFilteredEvents(allEvents);
    setSelectedColors([]);
    setSelectedUserIds([]);
  };

  const mergedLabels: CalendarLabels = { ...defaultCalendarLabels, ...labels };

  const value: ICalendarContext = {
    selectedDate,
    setSelectedDate: handleSelectDate,
    selectedUserIds,
    badgeVariant,
    setBadgeVariant,
    users,
    selectedColors,
    filterEventsBySelectedColors,
    filterEventsBySelectedUsers,
    clearUserFilter,
    events: filteredEvents,
    view: currentView,
    use24HourFormat,
    toggleTimeFormat,
    startOfDayHour,
    setStartOfDayHour,
    setView,
    agendaModeGroupBy,
    setAgendaModeGroupBy,
    addEvent,
    updateEvent,
    removeEvent,
    clearFilter,
    labels: mergedLabels,
    locale,
  };

  return (
    <CalendarContext.Provider value={value}>
      {children}
    </CalendarContext.Provider>
  );
}

export function useCalendar(): ICalendarContext {
  const context = useContext(CalendarContext);
  if (!context)
    throw new Error("useCalendar must be used within a CalendarProvider.");
  return context;
}

import React, {
  createContext,
  type ReactNode,
  useCallback,
  useContext,
  useRef,
  useState,
  useMemo,
} from "react";
import { toast } from "@/components/ui/toast";
import { useCalendar } from "./calendar-context";
import type { IEvent } from "../interfaces";

interface DragDropContextType {
  draggedEvent: IEvent | null;
  isDragging: boolean;
  startDrag: (event: IEvent) => void;
  endDrag: () => void;
  handleEventDrop: (date: Date, hour?: number, minute?: number) => void;
}

interface DndProviderProps {
  children: ReactNode;
}

const DragDropContext = createContext<DragDropContextType | undefined>(
  undefined,
);

export function DndProvider({ children }: DndProviderProps) {
  const { updateEvent, labels } = useCalendar();
  const [dragState, setDragState] = useState<{
    draggedEvent: IEvent | null;
    isDragging: boolean;
  }>({ draggedEvent: null, isDragging: false });

  const onEventDroppedRef = useRef<
    ((event: IEvent, newStartDate: Date, newEndDate: Date) => void) | null
  >(null);

  const startDrag = useCallback((event: IEvent) => {
    setDragState({ draggedEvent: event, isDragging: true });
  }, []);

  const endDrag = useCallback(() => {
    setDragState({ draggedEvent: null, isDragging: false });
  }, []);

  const calculateNewDates = useCallback(
    (event: IEvent, targetDate: Date, hour?: number, minute?: number) => {
      const originalStart = new Date(event.startDate);
      const originalEnd = new Date(event.endDate);
      const duration = originalEnd.getTime() - originalStart.getTime();

      const newStart = new Date(targetDate);
      if (hour !== undefined) {
        newStart.setHours(hour, minute || 0, 0, 0);
      } else {
        newStart.setHours(
          originalStart.getHours(),
          originalStart.getMinutes(),
          0,
          0,
        );
      }

      return {
        newStart,
        newEnd: new Date(newStart.getTime() + duration),
      };
    },
    [],
  );

  const isSamePosition = useCallback((date1: Date, date2: Date) => {
    return date1.getTime() === date2.getTime();
  }, []);

  const handleEventDrop = useCallback(
    (targetDate: Date, hour?: number, minute?: number) => {
      const { draggedEvent } = dragState;
      if (!draggedEvent) return;

      const { newStart, newEnd } = calculateNewDates(
        draggedEvent,
        targetDate,
        hour,
        minute,
      );
      const originalStart = new Date(draggedEvent.startDate);

      // Check if dropped in same position
      if (isSamePosition(originalStart, newStart)) {
        endDrag();
        return;
      }

      // Instantly update event
      const callback = onEventDroppedRef.current;
      if (callback) {
        callback(draggedEvent, newStart, newEnd);
      }
      endDrag();
    },
    [dragState, calculateNewDates, isSamePosition, endDrag],
  );

  // Default event update handler
  const handleEventUpdate = useCallback(
    (event: IEvent, newStartDate: Date, newEndDate: Date) => {
      try {
        const updatedEvent = {
          ...event,
          startDate: newStartDate.toISOString(),
          endDate: newEndDate.toISOString(),
        };
        updateEvent(updatedEvent);
        toast.add({ title: labels.toastEventMoved, type: "success" });
      } catch {
        toast.add({ title: labels.toastEventMoveFailed, type: "error" });
      }
    },
    [updateEvent, labels],
  );

  // Set default callback
  React.useEffect(() => {
    onEventDroppedRef.current = handleEventUpdate;
  }, [handleEventUpdate]);

  const contextValue = useMemo(
    () => ({
      draggedEvent: dragState.draggedEvent,
      isDragging: dragState.isDragging,
      startDrag,
      endDrag,
      handleEventDrop,
    }),
    [dragState, startDrag, endDrag, handleEventDrop],
  );

  return (
    <DragDropContext.Provider value={contextValue}>
      {children}
    </DragDropContext.Provider>
  );
}

export function useDragDrop() {
  const context = useContext(DragDropContext);
  if (!context) {
    throw new Error("useDragDrop must be used within a DragDropProvider");
  }
  return context;
}

import { useForm } from "@tanstack/react-form";
import { addMinutes, format, set } from "date-fns";
import { type ReactElement, useEffect, useMemo } from "react";

import { Button } from "@/components/ui/button";
import { DateTimeField } from "@/components/ui/date-time-field";
import { SelectField } from "@/components/ui/select-field";
import {
  Modal,
  ModalClose,
  ModalContent,
  ModalDescription,
  ModalFooter,
  ModalHeader,
  ModalTitle,
  ModalTrigger,
} from "@/components/ui/responsive-modal";
import { TextField } from "@/components/ui/text-field";
import { TextareaField } from "@/components/ui/textarea-field";
import { toast } from "@/components/ui/toast";
import { COLORS } from "../constants";
import { useCalendar } from "../contexts/calendar-context";
import { useDisclosure } from "../hooks";
import type { IEvent } from "../interfaces";
import { eventSchema } from "../schemas";
import type { TEventColor } from "../types";

interface IProps {
  children: ReactElement;
  startDate?: Date;
  startTime?: { hour: number; minute: number };
  event?: IEvent;
}

export function AddEditEventDialog({
  children,
  startDate,
  startTime,
  event,
}: IProps) {
  const { isOpen, onClose, onToggle } = useDisclosure();
  const { addEvent, updateEvent, use24HourFormat, labels } = useCalendar();
  const isEditing = !!event;

  const colorOptions = COLORS.map((color) => {
    const colorLabels: Record<TEventColor, string> = {
      blue: labels.colorBlue,
      green: labels.colorGreen,
      red: labels.colorRed,
      yellow: labels.colorYellow,
      purple: labels.colorPurple,
      orange: labels.colorOrange,
    };
    return {
      value: color,
      label: (
        <div className="flex items-center gap-2">
          <div className={`size-3.5 rounded-full bg-${color}-600 dark:bg-${color}-700`} />
          {colorLabels[color]}
        </div>
      ),
    };
  });

  const initialDates = useMemo(() => {
    if (!isEditing && !event) {
      if (!startDate) {
        const now = new Date();
        return { startDate: now, endDate: addMinutes(now, 30) };
      }
      const start = startTime
        ? set(new Date(startDate), {
            hours: startTime.hour,
            minutes: startTime.minute,
            seconds: 0,
          })
        : new Date(startDate);
      const end = addMinutes(start, 30);
      return { startDate: start, endDate: end };
    }

    return {
      startDate: new Date(event.startDate),
      endDate: new Date(event.endDate),
    };
  }, [startDate, startTime, event, isEditing]);

  const form = useForm({
    defaultValues: {
      title: event?.title ?? "",
      description: event?.description ?? "",
      startDate: initialDates.startDate,
      endDate: initialDates.endDate,
      color: (event?.color ?? "blue") as TEventColor,
    },
    validators: { onChange: eventSchema },
    onSubmit: ({ value }) => {
      try {
        const formattedEvent: IEvent = {
          ...value,
          startDate: format(value.startDate, "yyyy-MM-dd'T'HH:mm:ss"),
          endDate: format(value.endDate, "yyyy-MM-dd'T'HH:mm:ss"),
          id: isEditing ? event.id : Math.floor(Math.random() * 1000000),
          user: isEditing
            ? event.user
            : {
                id: Math.floor(Math.random() * 1000000).toString(),
                name: "Nicolas Thouvenin",
                picturePath: null,
              },
          color: value.color,
        };

        if (isEditing) {
          updateEvent(formattedEvent);
          toast.add({ title: labels.toastEventUpdated, type: "success" });
        } else {
          addEvent(formattedEvent);
          toast.add({ title: labels.toastEventCreated, type: "success" });
        }

        onClose();
        form.reset();
      } catch (error) {
        console.error(`Error ${isEditing ? "editing" : "adding"} event:`, error);
        toast.add({
          title: isEditing ? labels.toastEventEditFailed : labels.toastEventAddFailed,
          type: "error",
        });
      }
    },
  });

  useEffect(() => {
    form.reset({
      title: event?.title ?? "",
      description: event?.description ?? "",
      startDate: initialDates.startDate,
      endDate: initialDates.endDate,
      color: (event?.color ?? "blue") as TEventColor,
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [event, initialDates]);

  return (
    <Modal open={isOpen} onOpenChange={onToggle} modal={false}>
      <ModalTrigger render={children} />
      <ModalContent>
        <ModalHeader>
          <ModalTitle>
            {isEditing ? labels.dialogEditEventTitle : labels.dialogAddEventTitle}
          </ModalTitle>
          <ModalDescription>
            {isEditing
              ? labels.dialogEditEventDescription
              : labels.dialogAddEventDescription}
          </ModalDescription>
        </ModalHeader>

        <form
          id="event-form"
          onSubmit={(e) => {
            e.preventDefault();
            e.stopPropagation();
            form.handleSubmit();
          }}
          className="grid gap-4 py-4"
        >
          <form.Field name="title">
            {(field) => (
              <TextField
                field={field}
                label={labels.dialogFieldTitle}
                placeholder={labels.dialogTitlePlaceholder}
              />
            )}
          </form.Field>
          <form.Field name="startDate">
            {(field) => (
              <DateTimeField
                field={field}
                label={labels.dialogStartDate}
                use24HourFormat={use24HourFormat}
              />
            )}
          </form.Field>
          <form.Field name="endDate">
            {(field) => (
              <DateTimeField
                field={field}
                label={labels.dialogEndDate}
                use24HourFormat={use24HourFormat}
              />
            )}
          </form.Field>
          <form.Field name="color">
            {(field) => (
              <SelectField
                field={field}
                label={labels.dialogFieldVariant}
                placeholder={labels.dialogVariantPlaceholder}
                options={colorOptions}
              />
            )}
          </form.Field>
          <form.Field name="description">
            {(field) => (
              <TextareaField
                field={field}
                label={labels.dialogFieldDescription}
                placeholder={labels.dialogDescriptionPlaceholder}
              />
            )}
          </form.Field>
        </form>

        <ModalFooter className="flex justify-end gap-2">
          <ModalClose render={<Button type="button" variant="outline" />}>
            {labels.dialogCancel}
          </ModalClose>
          <Button form="event-form" type="submit">
            {isEditing ? labels.dialogSaveChanges : labels.dialogCreateEvent}
          </Button>
        </ModalFooter>
      </ModalContent>
    </Modal>
  );
}

import { TrashIcon } from "lucide-react";
import type { ReactElement } from "react";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { toast } from "@/components/ui/toast";
import { useCalendar } from "../contexts/calendar-context";

interface DeleteEventDialogProps {
  eventId: number;
}

export default function DeleteEventDialog({ eventId }: DeleteEventDialogProps) {
  const { removeEvent, labels } = useCalendar();

  const deleteEvent = () => {
    try {
      removeEvent(eventId);
      toast.add({ title: labels.toastEventDeleted, type: "success" });
    } catch {
      toast.add({ title: labels.toastEventDeleteError, type: "error" });
    }
  };

  if (!eventId) {
    return null;
  }

  const trigger = (
    <Button variant="destructive">
      <TrashIcon />
      {labels.dialogDeleteButton}
    </Button>
  ) as ReactElement;

  return (
    <AlertDialog>
      <AlertDialogTrigger render={trigger} />
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>{labels.dialogDeleteTitle}</AlertDialogTitle>
          <AlertDialogDescription>
            {labels.dialogDeleteDescription}
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel>{labels.dialogDeleteCancel}</AlertDialogCancel>
          <AlertDialogAction onClick={deleteEvent}>
            {labels.dialogDeleteContinue}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

import { format, parseISO } from "date-fns";
import { Calendar, Clock, Text, User } from "lucide-react";
import type { ReactElement } from "react";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { ScrollArea } from "@/components/ui/scroll-area";
import { toast } from "@/components/ui/toast";
import { useCalendar } from "../contexts/calendar-context";
import { AddEditEventDialog } from "./add-edit-event-dialog";
import { formatTime } from "../helpers";
import type { IEvent } from "../interfaces";

interface IProps {
  event: IEvent;
  children: ReactElement;
}

export function EventDetailsDialog({ event, children }: IProps) {
  const startDate = parseISO(event.startDate);
  const endDate = parseISO(event.endDate);
  const { use24HourFormat, removeEvent, locale, labels } = useCalendar();

  const deleteEvent = (eventId: number) => {
    try {
      removeEvent(eventId);
      toast.add({ title: labels.toastEventDeleted, type: "success" });
    } catch {
      toast.add({ title: labels.toastEventDeleteError, type: "error" });
    }
  };

  return (
    <Dialog>
      <DialogTrigger render={children} />
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{event.title}</DialogTitle>
        </DialogHeader>

        <ScrollArea className="max-h-[80vh]">
          <div className="space-y-4 p-4">
            <div className="flex items-start gap-2">
